"""Educational pretraining data (school -> undergraduate): Cosmopedia subsets (Apache-2.0, synthetic textbook/course-style text generated by Mixtral).
Downloads the remaining parquet shards into data/raw/cosmopedia/ (resumable). Shard 0 of each already exists from earlier."""
import os, subprocess
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "data", "raw", "cosmopedia")
def fetch(url, path):
    for _ in range(8):
        if subprocess.run(["curl", "-L", "-sS", "-C", "-", "--retry", "5", "--retry-delay", "5", "-o", path + ".part", url]).returncode == 0: os.replace(path + ".part", path); return
    raise RuntimeError(url)
B = "https://huggingface.co/datasets/HuggingFaceTB/cosmopedia/resolve/main/data"
PLAN = [("openstax", 2, [1]), ("stanford", 13, [1, 2, 3, 4, 5])]
for name, n, idx in PLAN:
    for i in idx:
        p = os.path.join(OUT, f"{name}_{i}.parquet")
        if not os.path.exists(p): fetch(f"{B}/{name}/train-{i:05d}-of-{n:05d}.parquet", p)
        print(name, i, round(os.path.getsize(p) / 1e6), "MB", flush=True)
open(os.path.join(OUT, "..", "..", "..", "logs", "dl_edu_done.flag"), "w").write("0")
